def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    patterns = []
    # Every multi-cell horizontal run is a template; singletons are instances.
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start > 1:
                patterns.append(row[start:c])
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color == 0:
                continue
            if (c > 0 and row[c - 1] != 0) or (c + 1 < w and row[c + 1] != 0):
                continue
            for pattern in patterns:
                if color in pattern:
                    left = c - pattern.index(color)
                    for k, value in enumerate(pattern):
                        x = left + k
                        if 0 <= x < w:
                            out[r][x] = value
                    break
    return out
